$ErrorActionPreference = 'Stop'
Set-Location (Split-Path $PSScriptRoot -Parent)
New-Item -ItemType Directory -Force artifacts/app-demo | Out-Null
Add-Type -AssemblyName System.Speech
$speech = New-Object System.Speech.Synthesis.SpeechSynthesizer
$speech.SelectVoice('Microsoft Irina Desktop')
$speech.Rate = 0
$chapters = @(
    @{title='Знакомство с приложением'; action=''; text='Перед вами приложение учебной антифрод платформы. Покажем два сценария защиты переадресации. Все аккаунты, сетевые сигналы и назначения синтетические. Приложение обращается к работающему серверу.'},
    @{title='Подозрительная операция'; action='fraud'; text='Выбираем демо фрод. В этом сценарии сервер видит смену сим карты, новое устройство и невозможное перемещение между городами. Нажимаем проверить защищённое действие. Сервер возвращает холд. Операция приостановлена.'},
    @{title='Проверяем результат блокировки'; action='state-fraud'; text='Проверяем состояние услуги. На сервере переадресация отключена. Число изменений равно нулю. Подозрительный запрос не изменил услугу. Решение и события сохранены в аудите.'},
    @{title='Легитимный сценарий'; action='legal'; text='Теперь выбираем демо легал и снова проверяем защищённое действие. Здесь устройство знакомое, а перемещение допустимо, но сим карта изменилась. Ответ степ ап означает, что перед исполнением нужно дополнительное подтверждение.'},
    @{title='Подтверждение конкретного действия'; action='confirm'; text='Приложение показывает аккаунт и назначение синк эй. Нажимаем тестовую кнопку подтверждения. Сервер возвращает элау, то есть разрешение. Это учебная подстановка, а не настоящее независимое подтверждение. Команда доставляется отдельно после сохранения решения.'},
    @{title='Проверяем исполнение'; action='state-legal'; text='Снова проверяем состояние услуги. Теперь сервер показывает назначение синк эй и одно изменение. Значит, переадресация действительно включена в локальном симуляторе. В аудите сохранены решение, подтверждение и результат исполнения.'},
    @{title='Итоги'; action=''; text='Мы увидели полный путь в приложении. Подозрительная операция остановлена, а легитимная выполнена после подтверждения. Это изолированный учебный стенд. Реальные абоненты и операторская сеть в демонстрации не используются.'}
)
for ($i=0; $i -lt $chapters.Count; $i++) {
    $speech.SetOutputToWaveFile("$PWD/artifacts/app-demo/voice-$i.wav")
    $speech.Speak($chapters[$i].text)
    $speech.SetOutputToNull()
}
$speech.Dispose()
$chapters | ConvertTo-Json -Depth 3 | Set-Content artifacts/app-demo/chapters.json -Encoding UTF8
python scripts/record-app-demo.py
if ($LASTEXITCODE) { throw 'Recording failed' }
